def snap_hz(x):
    """Ближайшая стандартная частота экрана; None — если замер не похож на реальный (нет vsync)."""
    if x <= 0:
        return None
    best = min(STD_HZ, key=lambda h: abs(h - x))
    return best if abs(best - x) <= best * 0.06 else None


def android_display_hz():
    """Частота экрана по данным Android: (текущая, максимальная) в Гц; None — не Android или не вышло."""
    if platform != 'android':
        return None
    try:
        from jnius import autoclass
        act = autoclass('org.kivy.android.PythonActivity').mActivity
        sdk = autoclass('android.os.Build$VERSION').SDK_INT
        disp = None
        if sdk >= 30:
            try:
                disp = act.getDisplay()
            except Exception:
                disp = None
        if disp is None:
            disp = act.getWindowManager().getDefaultDisplay()
        cur = float(disp.getRefreshRate())
        top = cur
        if sdk >= 23:
            for m in disp.getSupportedModes():          # все режимы экрана — берём самый быстрый
                top = max(top, float(m.getRefreshRate()))
        return cur, top
    except Exception:
        return None


def android_power_save():
    """True, если на телефоне включён режим энергосбережения."""
    if platform != 'android':
        return False
    try:
        from jnius import autoclass
        act = autoclass('org.kivy.android.PythonActivity').mActivity
        ctx = autoclass('android.content.Context')
        return bool(act.getSystemService(ctx.POWER_SERVICE).isPowerSaveMode())
    except Exception:
        return False
