class LanLink:
    """UDP-соединение для игры по локальной сети: поиск комнат, подключение и обмен
    позицией во время забега. Приём пакетов идёт в фоновом потоке и складывается в
    очередь — его разбирает главный поток в Game.lan_poll(), как и положено в Kivy."""
    def __init__(self):
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        self.sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        try:
            self.sock.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
        except OSError:
            pass
        try:
            self.sock.bind(('', LAN_PORT))
        except OSError:
            self.sock.bind(('', 0))          # порт занят (например, второй игрок на этом же ПК)
        self.sock.settimeout(0.2)
        self.q = queue.Queue()
        self.running = True
        self.thread = threading.Thread(target=self._loop, daemon=True)
        self.thread.start()

    def _loop(self):
        while self.running:
            try:
                data, addr = self.sock.recvfrom(1024)
                self.q.put((data.decode('utf-8', 'ignore'), addr))
            except socket.timeout:
                continue
            except OSError:
                break

    def send(self, msg, addr):
        if not addr:
            return
        try:
            self.sock.sendto(msg.encode('utf-8'), addr)
        except OSError:
            pass

    def broadcast(self, msg):
        try:
            self.sock.sendto(msg.encode('utf-8'), ('255.255.255.255', LAN_PORT))
        except OSError:
            pass

    def poll(self):
        """Все сообщения, пришедшие с прошлого вызова: список (текст, адрес)."""
        out = []
        while True:
            try:
                out.append(self.q.get_nowait())
            except queue.Empty:
                break
        return out

    def close(self):
        self.running = False
        try:
            self.sock.close()
        except OSError:
            pass


class Game(Widget):
    def __init__(self, save_file, **kw):
        super().__init__(**kw)
        self.save_file, self.tex_cache = save_file, {}
        self.cfg = dict(self.defaults())
        self.page, self.brand, self.menu_obs = 0, 0, 0
        self.shop_brand = None            # выбранный бренд в магазине (None — показать кнопки брендов)
        self.mode = 'single'
        self.bot_dist = 0.0
        self.pending = None               # выбранный в магазине, но ещё не купленный скин
        self.msg_text, self.msg_t, self.reset_t = '', 0.0, 0.0
        self.code_popup = None
        self.toast, self.toast_t, self.toast_q = ('', ''), 0.0, []
        self.s, self.ww, self.oy, self.px0 = 4.0, 222.0, 0.0, 62.0
        self.jx = self.jy = 0.0           # тряска экрана
        self.alpha = 1.0                  # общая прозрачность рисования
        self.clock = self.scroll = self.run_ph = 0.0
        self.new_best, self.tab, self.btns = False, 0, []   # tab: 0 — охотник, 1 — герой
        self.splash_t = 0.0
        self.rng = random.Random()          # отдельный ГСЧ для препятствий (сидируется для LAN-гонки)
        # ---------- игра по локальной сети ----------
        self.lan = None                     # активное соединение (LanLink) или None
        self.lan_role = None                # 'host' | 'client'
        self.lan_code = ''                  # код комнаты хоста (4 цифры)
        self.lan_hosts = []                 # найденные комнаты при поиске: [(код, адрес), ...]
        self.lan_search_t = 0.0
        self.lan_peer_addr = None
        self.lan_peer_dist = 0.0
        self.lan_peer_alive = True
        self.lan_result = 'wait'            # 'wait' | 'win' | 'lose'
        self.lan_send_t = 0.0
        self.load()
        self.load_assets()
        rnd = random.Random(7)
        self.stars = [(rnd.random(), rnd.uniform(0.45, 0.98)) for _ in range(45)]
        self.city, x = [], 0.0            # силуэт города: (x, ширина, высота, окна)
        while x < 300:
            w, h = rnd.uniform(10, 22), rnd.uniform(14, 42)
            wins = [(wx, wy) for wx in range(2, int(w) - 1, 4)
                    for wy in range(4, int(h) - 2, 6) if rnd.random() < 0.45]
            self.city.append((x, w, h, wins))
            x += w + rnd.uniform(0, 4)
        self.city_w = x
        self.make_decor(rnd)
        self.reset()          # инициализируем списки/физику до первого кадра заставки
        self.to_splash()
        self.bind(size=self.fit)
        self.fit()
        Window.bind(on_key_down=self.on_key)
        self.init_display()               # узнаём частоту экрана и выбираем FPS

    # ---------- декорации фонов ----------
    def make_decor(self, rnd):
        """Заранее раскладывает барханы, кактусы, деревья. Каждый слой: (предметы, период)."""
        def build(make, lo, hi):
            items, x = [], 0.0
            while x < 300:
                it = make(x, rnd)
                items.append(it)
                x += rnd.uniform(lo, hi)
            return items, x
        self.dunes_far = build(lambda x, r: (x, r.uniform(32, 56), r.uniform(9, 18)), 40, 70)
        self.dunes_near = build(lambda x, r: (x, r.uniform(22, 40), r.uniform(5, 11)), 30, 50)
        self.cacti = build(lambda x, r: (x, r.uniform(9, 16), r.random() < 0.5), 38, 90)
        self.hills = build(lambda x, r: (x, r.uniform(34, 60), r.uniform(10, 22)), 45, 80)
        self.trees_far = build(lambda x, r: (x, r.uniform(14, 22), r.uniform(0.7, 1.0)), 10, 24)
        self.trees_near = build(lambda x, r: (x, r.uniform(22, 34), r.uniform(0.8, 1.0)), 24, 52)
        self.clouds = build(lambda x, r: (x, r.uniform(62, 88), r.uniform(8, 15)), 55, 110)
        # заброшка: далёкие и ближние руины, мёртвые деревья, забор
        self.ruins_far = build(lambda x, r: (x, r.uniform(14, 26), r.uniform(18, 40), r.random()), 16, 30)
        self.ruins_near = build(lambda x, r: (x, r.uniform(12, 20), r.uniform(12, 26), r.random()), 40, 80)
        self.dead_trees = build(lambda x, r: (x, r.uniform(14, 26), r.random() < 0.5), 30, 70)
        self.fence = build(lambda x, r: (x, r.random() < 0.18), 5, 5.01)
        # Москва: Сити, Останкино, Кремль со Спасской башней и собором Василия Блаженного
        self.msk_city = build(lambda x, r: (x, r.uniform(8, 15), r.uniform(26, 58), r.random() < 0.3), 9, 17)
        kr, x = [], 0.0
        for kind in ('wall', 'tower', 'wall', 'basil', 'wall', 'spasskaya', 'wall', 'tower'):
            if kind == 'wall':
                w = rnd.uniform(26, 38)
                kr.append((x, 'wall', w, 0.0))
                x += w
            elif kind == 'tower':
                kr.append((x, 'tower', 7.0, rnd.uniform(15, 22)))
                x += 7.0
            elif kind == 'spasskaya':
                kr.append((x, 'spasskaya', 8.0, 30.0))
                x += 8.0
            else:
                kr.append((x, 'basil', 34.0, 0.0))
                x += 36.0
        self.kremlin = (kr, max(x + 10, 260.0))
        self.ostankino = ([(60.0,)], 300.0)

    def layer(self, deco, factor, fn):
        """Рисует слой декораций, едущий медленнее дороги (параллакс)."""
        items, period = deco
        off = -((self.scroll * factor) % period)
        for rep in (0, 1):
            for it in items:
                x = off + rep * period + it[0]
                if -70 < x < self.ww + 70:
                    fn(x, *it[1:])

    def oval(self, cx, cy, rx, ry, col):
        Color(col[0], col[1], col[2], col[3] * self.alpha)
        Ellipse(pos=(self.sx(cx - rx), self.sy(cy - ry)), size=(2 * rx * self.s, 2 * ry * self.s))

    def tri(self, x, y, w, h, col):
        Color(col[0], col[1], col[2], col[3] * self.alpha)
        Triangle(points=[self.sx(x), self.sy(y), self.sx(x + w), self.sy(y),
                         self.sx(x + w / 2), self.sy(y + h)])

    # ---------- подгонка под экран и поворот ----------
    def fit(self, *_):
        self.s = max(0.1, min(self.height / WORLD_H, self.width / MIN_W))
        self.ww = self.width / self.s                       # ширина мира в единицах
        self.oy = (self.height - WORLD_H * self.s) / 2      # поле по центру по высоте
        self.px0 = min(80.0, max(40.0, self.ww * 0.28))     # x героя
        self.tex_cache = {}

    # ---------- файлы: настройки, картинки, звуки ----------
    @staticmethod
    def defaults():
        return {'ver': 3, 'best': 0, 'vibro': True, 'sound': True, 'hunter': 0, 'hero': 0,
                'coins': 0, 'earned': 0, 'ach': [False] * len(ACH), 'owned': [],
                'fps': 60, 'fps_auto': True, 'bg': 1, 'promos': [], 'free_pick': 0, 'jump_level': 0, 'run_level': 0}

    def load(self):
        try:
            with open(self.save_file) as f:
                d = json.load(f)
            old = d.get('ver', 0) < 3
            for k in self.cfg:
                if k in d:
                    self.cfg[k] = d[k]
            cfg = self.cfg
            for k in KEYS:
                cfg[k] = max(0, min(len(SKIN_NAMES) - 1, int(cfg[k])))
            cfg['coins'] = max(0, int(cfg['coins']))
            cfg['earned'] = max(int(cfg['earned']), cfg['coins'])
            # в старых сохранениях 3-е достижение было «получить все» — оно удалено
            ach = [bool(a) for a in list(cfg['ach'])[:2 if old else len(ACH)]]
            cfg['ach'] = ach + [False] * (len(ACH) - len(ach))
            cfg['owned'] = sorted({int(i) for i in cfg['owned'] if 0 <= int(i) < len(SKINS)})
            cfg['fps'] = cfg['fps'] if cfg['fps'] in FPS_LIST else 60
            cfg['fps_auto'] = bool(cfg.get('fps_auto', True))
            cfg['bg'] = cfg['bg'] if cfg['bg'] in range(len(BG_NAMES)) else 1
            cfg['promos'] = [str(p) for p in cfg['promos']]
            cfg['free_pick'] = max(0, int(cfg['free_pick']))
            cfg['jump_level'] = max(0, min(3, int(cfg.get('jump_level', 0))))
            cfg['run_level'] = max(0, min(3, int(cfg.get('run_level', 0))))
            cfg['ver'] = 3
        except Exception:
            pass
        for k in KEYS:                                      # чужой скин выбранным быть не может
            if not self.owned(self.cfg[k]):
                self.cfg[k] = 0

    def owned(self, i):
        return i in FREE or i in self.cfg['owned']

    def save(self):
        try:
            with open(self.save_file, 'w') as f:
                json.dump(self.cfg, f)
        except Exception:
            pass

    def load_assets(self):
        """Достаёт картинки и звуки, встроенные в конец файла."""
        self.pics, self.snd = {}, {}
        dec = lambda b: base64.b64decode(''.join(b.split()))
        for i, b in enumerate(SKINS_B64):
            try:
                self.pics[i] = CoreImage(io.BytesIO(dec(b)), ext='png').texture
            except Exception:
                pass
        try:
            self.coin_tex = CoreImage(io.BytesIO(dec(COIN_B64)), ext='png').texture
        except Exception:
            self.coin_tex = None
        try:
            self.smile_tex = CoreImage(io.BytesIO(dec(SMILE_B64)), ext='png').texture
        except Exception:
            self.smile_tex = None
        cache = os.path.dirname(self.save_file)
        for n, b in SOUNDS_B64.items():
            try:
                os.makedirs(cache, exist_ok=True)
                path = os.path.join(cache, n + '.wav')
                with open(path, 'wb') as f:
                    f.write(dec(b))
                self.snd[n] = SoundLoader.load(path)
            except Exception:
                pass

    def sfx(self, name):
        s = self.snd.get(name)
        if self.cfg['sound'] and s:
            try:
                s.stop()
                s.play()
            except Exception:
                pass

    def vibrate(self, ms):
        if not self.cfg['vibro'] or platform != 'android':
            return
        try:
            from jnius import autoclass
            act = autoclass('org.kivy.android.PythonActivity').mActivity
            ctx = autoclass('android.content.Context')
            act.getSystemService(ctx.VIBRATOR_SERVICE).vibrate(int(ms))
        except Exception:
            try:
                from plyer import vibrator          # запасной вариант (например, Pydroid)
                vibrator.vibrate(time=ms / 1000)
            except Exception:
                pass

    # ---------- состояние ----------
    def reset(self):
        self.state, self.speed, self.dist = 'play', START_SPEED * (1 + self.cfg.get('run_level', 0) * 0.025), 0.0
        self.bot_dist, self.bot_alive = 0.0, True           # соперник-ИИ (режим «с ботами»)
        self.bot_speed, self.bot_gap = START_SPEED, START_GAP
        self.bot_rate = random.uniform(*BOT_RATE)           # «неаккуратность» ИИ в этом забеге
        self.bot_skin, self.bot_result = random.choice(POOL), ''
        self.ph = self.vy = 0.0                             # высота героя над дорогой
        self.jumps = 2
        self.obs, self.parts, self.coins, self.secrets = [], [], [], []
        self.toast_q, self.toast_t = [], 0.0
        self.next_coin = COIN_EVERY                         # метры до следующей монеты
        self.next_secret = SECRET_EVERY                     # и до секретного телефона
        self.gap = self.gap_t = START_GAP                   # текущая и целевая дистанция до охотника
        self.inv = self.shake = self.flash = self.dust_t = self.over_t = 0.0
        self.spawn_t = 1.0

    def to_splash(self):
        self.state, self.splash_t = 'splash', 0.0

    def to_menu(self):
        self.lan_close()
        self.reset()
        self.menu_obs = random.choice(POOL)        # случайный скин-препятствие в меню
        self.state, self.speed, self.mode = 'menu', 70.0, 'single'
        self.gap = self.gap_t = 28.0

    def meters(self):
        return int(self.dist / 10)

    def pause(self):
        if self.state == 'play':
            self.state = 'pause'

    # ---------- управление ----------
    def on_touch_down(self, touch):
        if self.state == 'splash':          # заставку пропустить нельзя — тапы съедаем
            return True
        wx, wy = (touch.x - self.x) / self.s, (touch.y - self.y - self.oy) / self.s
        for name, x, y, w, h in self.btns:
            if x <= wx <= x + w and y <= wy <= y + h:
                self.click(name)
                return True
        if self.state == 'play':
            self.jump()
        return True

    def on_key(self, win, key, *args):
        if key in (32, 273, 119) and self.state in ('play', 'menu') and not self.code_popup:
            if self.state == 'play':        # пробел, стрелка вверх, W — для проверки на ПК
                self.jump()
            else:
                self.click('play')
            return True

    def click(self, name):
        cfg = self.cfg
        if name == 'play':                                  # «Играть» открывает выбор режима
            self.state = 'play_modes'
            self.sfx('click')
        elif name == 'again':
            if self.state == 'pause' and self.meters() > cfg['best']:
                cfg['best'] = self.meters()
                self.save()
            self.reset()                                    # режим (одиночный / с ИИ) сохраняется
        elif name == 'mode_single':
            self.mode = 'single'
            self.rng = random.Random()
            self.reset()
        elif name == 'mode_bot':
            self.mode = 'bot'
            self.rng = random.Random()
            self.reset()
        elif name == 'mode_lan':
            self.state = 'lan_menu'
            self.sfx('click')
        elif name.startswith('upgrade_'):
            self.buy_upgrade('jump_level' if name == 'upgrade_jump' else 'run_level',
                             'Прыжок' if name == 'upgrade_jump' else 'Бег')
        elif name in ('settings', 'skins', 'ach', 'upgrades'):
            self.state = name
            self.pending = None
            self.show_skin(cfg[KEYS[self.tab]])
        elif name in ('prev', 'next'):
            pages = max(1, (len(self.cur_ids()) + PER_PAGE - 1) // PER_PAGE)
            self.page = (self.page + (1 if name == 'next' else -1)) % pages
            self.sfx('click')
        elif name.startswith('sec'):
            self.brand, self.page, self.pending = int(name[3:]), 0, None
            self.shop_brand = None                          # «Магазин» всегда открывается с кнопок брендов
            self.sfx('click')
        elif name.startswith('shb'):                        # выбрали бренд в магазине
            self.shop_brand, self.page, self.pending = SHOP_BRANDS[int(name[3:])], 0, None
            self.sfx('click')
        elif name == 'back' and self.state == 'skins' and self.brand == 1 and self.shop_brand is not None:
            self.shop_brand, self.page, self.pending = None, 0, None   # из бренда — обратно к кнопкам брендов
            self.sfx('click')
        elif name == 'back' and self.state == 'lan_menu':
            self.state = 'play_modes'                       # из «Игры по сети» — к выбору режима
        elif name in ('back', 'menu'):
            if self.state == 'pause' and self.meters() > cfg['best']:
                cfg['best'] = self.meters()                 # выход из паузы тоже сохраняет рекорд
                self.save()
            self.to_menu()
        elif name == 'pause':
            self.state = 'pause' if self.state == 'play' else 'play'
        elif name in ('vibro', 'sound'):
            cfg[name] = not cfg[name]
            self.save()
            self.sfx('click')
            self.vibrate(40)
        elif name == 'fps':
            al = self.fps_allowed()
            if len(al) < 2:                                 # экран не тянет больше — переключать некуда
                self.say(f'Экран {self.hz} Гц: выше {al[-1]} FPS недоступно')
            else:
                i = al.index(self.fps) if self.fps in al else len(al) - 1
                cfg['fps'] = al[(i + 1) % len(al)]
                cfg['fps_auto'] = cfg['fps'] == al[-1]      # максимум для экрана = «авто»
                self.apply_fps()
                self.save()
                self.sfx('click')
        elif name == 'bg':
            cfg['bg'] = (cfg['bg'] + 1) % len(BG_NAMES)
            self.save()
            self.sfx('click')
        elif name == 'reset':
            if self.reset_t > 0:                            # второе нажатие — подтверждение
                self.reset_t = 0.0
                keep = {k: cfg[k] for k in ('vibro', 'sound', 'fps', 'fps_auto', 'bg')}
                cfg.clear()
                cfg.update(self.defaults())
                cfg.update(keep)
                self.pending = None
                self.save()
                self.say('Прогресс и достижения сброшены')
            else:
                self.reset_t = 3.0
                self.say('Нажми ещё раз, чтобы всё сбросить')
        elif name == 'code':
            self.ask_code('dev')
        elif name == 'promo':
            self.ask_code('promo')
        elif name == 'lan':
            self.state = 'lan_menu'
        elif name == 'lan_host':
            self.lan_start_host()
        elif name == 'lan_search':
            self.lan_start_search()
        elif name == 'lan_cancel':
            self.lan_close()
            self.state = 'lan_menu'
        elif name.startswith('lan_join'):
            idx = int(name[8:])
            if self.lan and idx < len(self.lan_hosts):
                _, addr = self.lan_hosts[idx]
                self.lan_peer_addr = addr
                self.lan.send(f'{LAN_MAGIC}|JOIN', addr)
                self.state = 'lan_wait'
                self.say('Подключаемся...')
        elif name.startswith('tab'):
            self.tab = int(name[3:])
            self.pending = None
            self.show_skin(cfg[KEYS[self.tab]])
        elif name.startswith('skin'):
            i = int(name[4:])
            if self.owned(i):                               # чужой скин выбрать нельзя
                cfg[KEYS[self.tab]] = i
                self.pending = None
                self.save()
                self.sfx('click')
            elif i in SECRET:
                self.say('Секретный: выпадает в забеге раз в 5000 м')
            else:
                self.pending = i
                self.sfx('click')
        elif name == 'buy' and self.pending is not None:
            i, cost = self.pending, price(self.pending)
            if cfg['free_pick'] > 0:                        # промокод: телефон бесплатно
                cost = 0
            if cfg['coins'] >= cost:                        # монеты отбираются навсегда
                if cost == 0:
                    cfg['free_pick'] -= 1
                cfg['coins'] -= cost
                cfg['owned'] = sorted(set(cfg['owned']) | {i})
                cfg[KEYS[self.tab]] = i
                self.pending = None
                self.save()
                self.sfx('click')
                self.vibrate(40)
                self.say(f'Куплено: {SKIN_NAMES[i]}')
            else:
                self.say(f'Не хватает монет: нужно {cost}, есть {cfg["coins"]}')
                self.vibrate(40)

    def buy_upgrade(self, key, title):
        """Улучшение прыжка/бега: 3 уровня, каждый стоит 3 снапа (монеты Snapdragon)."""
        cfg = self.cfg
        lvl = cfg.get(key, 0)
        if lvl >= UPGRADE_MAX:
            self.say(f'{title}: уже максимальный уровень')
        elif cfg['coins'] < UPGRADE_PRICE:
            self.say(f'Не хватает монет: нужно {UPGRADE_PRICE}, есть {cfg["coins"]}')
            self.vibrate(40)
        else:
            cfg['coins'] -= UPGRADE_PRICE
            cfg[key] = lvl + 1
            self.save()
            self.sfx('click')
            self.vibrate(40)
            self.say(f'{title}: уровень {lvl + 1}/{UPGRADE_MAX}')

    def ask_code(self, mode='dev'):
        """Окошко для ввода кода разработчика или промокода."""
        if self.code_popup:
            return
        from kivy.uix.boxlayout import BoxLayout
        from kivy.uix.button import Button
        from kivy.uix.popup import Popup
        from kivy.uix.textinput import TextInput
        box = BoxLayout(orientation='horizontal', spacing=8, padding=8)
        ti = TextInput(multiline=False, hint_text='Промокод' if mode == 'promo' else 'Код', font_size='22sp', write_tab=False)
        ok = Button(text='OK', size_hint_x=0.3, font_size='20sp')
        box.add_widget(ti)
        box.add_widget(ok)
        pop = Popup(title='Промокоды' if mode == 'promo' else 'Код разработчика', content=box, size_hint=(0.8, None), height='120dp',
                    pos_hint={'center_x': 0.5, 'top': 0.98}, auto_dismiss=True)

        def submit(*_):
            text = ti.text
            pop.dismiss()
            (self.apply_promo if mode == 'promo' else self.apply_code)(text)

        ok.bind(on_release=submit)
        ti.bind(on_text_validate=submit)
        pop.bind(on_dismiss=lambda *_: setattr(self, 'code_popup', None))
        self.code_popup = pop
        pop.open()
        Clock.schedule_once(lambda dt: setattr(ti, 'focus', True), 0.2)

    def apply_promo(self, text):
        cfg = self.cfg
        p = PROMO_MAP.get(norm(text))
        if not p:
            self.say('Неверный промокод')
            return
        code, kind, n = p
        if code in cfg['promos']:
            self.say('Этот промокод уже использован')
            return
        if kind == 'coins':
            cfg['coins'] += n
            self.say(f'Промокод принят: +{n} монет Snapdragon')
        elif kind in ('secret', 'shop'):
            pool = [i for i in (SECRET if kind == 'secret' else SHOP)
                    if not self.owned(i) and (kind == 'secret' or price(i) == n)]
            if not pool:
                self.say('Все такие телефоны у тебя уже есть')
                return
            i = random.choice(pool)
            cfg['owned'] = sorted(set(cfg['owned']) | {i})
            self.say(f'Промокод принят: {SKIN_NAMES[i]}')
        elif kind == 'brand':                               # один телефон нужного бренда из магазина
            pool = [i for i in SHOP if SKINS[i][1] == n and not self.owned(i)]
            if not pool:
                self.say('Все такие телефоны у тебя уже есть')
                return
            i = random.choice(pool)
            cfg['owned'] = sorted(set(cfg['owned']) | {i})
            self.say(f'Промокод принят: {SKIN_NAMES[i]}')
        else:                                               # любой телефон из магазина бесплатно
            cfg['free_pick'] += 1
            self.say('Промокод принят: выбери любой телефон в Магазине')
        cfg['promos'].append(code)
        self.sfx('click')
        self.vibrate(40)
        self.save()

    def apply_code(self, text):
        text = norm(text)
        if text in DEV_CODES:
            self.cfg['owned'] = list(range(len(SKINS)))     # все телефоны
            self.cfg['ach'] = [True] * len(ACH)             # все достижения
            self.cfg['jump_level'] = self.cfg['run_level'] = UPGRADE_MAX   # и улучшения
            self.save()
            self.sfx('click')
            self.say('Код принят: всё разблокировано!')
        else:
            self.say('Неверный код')

    # ---------- игра по локальной сети ----------
    def lan_start_host(self):
        """Создаёт комнату: слушает подключения по Wi-Fi и ждёт соперника."""
        self.lan_close()
        try:
            self.lan = LanLink()
        except OSError:
            self.say('Не удалось открыть локальную сеть')
            return
        self.lan_role = 'host'
        self.lan_code = f'{random.randint(0, 9999):04d}'
        self.state = 'lan_wait'

    def lan_start_search(self):
        """Ищет комнаты, открытые другими телефонами в этой же Wi-Fi сети."""
        self.lan_close()
        try:
            self.lan = LanLink()
        except OSError:
            self.say('Не удалось открыть локальную сеть')
            return
        self.lan_role = 'client'
        self.lan_hosts, self.lan_search_t = [], 0.0
        self.state = 'lan_search'

    def lan_close(self):
        """Закрывает текущее сетевое соединение (если оно было) и сообщает сопернику."""
        if self.lan:
            if self.lan_peer_addr:
                self.lan.send(f'{LAN_MAGIC}|BYE', self.lan_peer_addr)
            self.lan.close()
        self.lan, self.lan_role, self.lan_peer_addr, self.lan_hosts = None, None, None, []

    def lan_begin_race(self, seed):
        """Запускает синхронный забег: оба игрока получают одинаковую последовательность
        препятствий благодаря общему сиду seed (см. self.rng в spawn() и play())."""
        self.rng = random.Random(seed)
        self.mode = 'lan'
        self.lan_peer_dist, self.lan_peer_alive = 0.0, True
        self.lan_result, self.lan_send_t = 'wait', 0.0
        self.reset()

    def lan_poll(self):
        """Разбирает пакеты, пришедшие от LanLink с прошлого кадра (вызывается каждый кадр)."""
        if not self.lan:
            return
        for text, addr in self.lan.poll():
            parts = text.split('|')
            if len(parts) < 2 or parts[0] != LAN_MAGIC:
                continue                                    # не наш протокол — игнорируем
            kind = parts[1]
            if kind == 'FIND' and self.lan_role == 'host':
                self.lan.send(f'{LAN_MAGIC}|HOST|{self.lan_code}', addr)
            elif kind == 'HOST' and self.lan_role == 'client' and self.state == 'lan_search':
                code = parts[2] if len(parts) > 2 else '????'
                if not any(a == addr for _, a in self.lan_hosts):
                    self.lan_hosts.append((code, addr))
            elif kind == 'JOIN' and self.lan_role == 'host':
                self.lan_peer_addr = addr
                seed = random.randint(0, 2 ** 31 - 1)
                self.lan.send(f'{LAN_MAGIC}|ACCEPT|{seed}', addr)
                self.lan_begin_race(seed)
            elif kind == 'ACCEPT' and self.lan_role == 'client':
                self.lan_peer_addr = addr
                seed = int(parts[2]) if len(parts) > 2 else 0
                self.lan_begin_race(seed)
            elif kind == 'POS' and len(parts) > 2:
                try:
                    self.lan_peer_dist = float(parts[2])
                except ValueError:
                    pass
            elif kind == 'DEAD':
                self.lan_peer_alive = False
                if len(parts) > 2:
                    try:
                        self.lan_peer_dist = float(parts[2])
                    except ValueError:
                        pass
                if self.state == 'lan_over' and self.lan_result == 'wait':
                    self.lan_result = 'win' if self.dist >= self.lan_peer_dist else 'lose'
            elif kind == 'BYE':
                self.lan_peer_alive = False
                if self.state == 'play':
                    self.say('Соперник вышел из игры')

    def show_skin(self, i):
        """Открывает вкладку бренда и страницу, где лежит скин i."""
        self.brand = 0 if i in FREE else 2 if i in SECRET else 1
        self.shop_brand = SKINS[i][1] if self.brand == 1 else None
        self.page = self.cur_ids().index(i) // PER_PAGE

    def cur_ids(self):
        """Скины на открытой вкладке: в магазине — только выбранного бренда, по редкости."""
        if self.brand == 1:
            return [i for i in SHOP if SKINS[i][1] == self.shop_brand] if self.shop_brand else []
        return SECTION_IDS[self.brand]

    def jump(self):
        if self.jumps > 0:
            boost = 1.0 + self.cfg.get('jump_level', 0) * 0.035
            self.vy = (JUMP_V if self.jumps == 2 else JUMP_V * 0.9) * boost
            self.jumps -= 1
            self.puff(self.px0 + PW / 2, GROUND + self.ph, 5, DUST, 22)
            self.sfx('jump')

    # ---------- логика ----------
    # ---------- частота экрана и энергосбережение ----------
    def init_display(self):
        """Узнаёт, сколько герц у экрана, и включает подходящий FPS (выше — заблокировано)."""
        self.hz, self.hz_ready, self.probing = 60, False, False
        self.power_save, self.pw_t, self.cur_fps, self.fps = False, 8.0, 0, 60
        self.probe, self._pn = [], 0
        info = android_display_hz()                 # Android: спрашиваем систему
        if info:
            self.hz, self.hz_ready = snap_hz(info[1]) or int(round(info[1])), True
        self.power_save = android_power_save()
        self.apply_fps()
        if not self.hz_ready:                       # ПК и прочее: меряем сами во время заставки
            self.probing = True
            self.set_fps(60)
            Clock.schedule_interval(self._probe_cb, 0)

    def _probe_cb(self, dt):
        """Замер реальной частоты кадров экрана (при включённом vsync кадр = один оборот экрана)."""
        self._pn += 1
        if self._pn > 8:                            # первые кадры — прогрев
            self.probe.append(dt)
        if len(self.probe) >= 50 or sum(self.probe) > 1.5:
            Clock.unschedule(self._probe_cb)
            self.probing = False
            hz = None
            if len(self.probe) >= 10:
                med = sorted(self.probe)[len(self.probe) // 2]
                hz = snap_hz(1.0 / med) if med > 0 else None
            self.hz, self.hz_ready = hz or 60, True     # не удалось — безопасные 60
            self.apply_fps()

    def fps_cap(self):
        """Потолок FPS: частота экрана; в режиме энергосбережения — не больше 60."""
        cap = self.hz
        if self.power_save:
            cap = min(cap, 60)
        return max(30, int(cap))

    def fps_allowed(self):
        """Режимы FPS, доступные на этом экране."""
        cap = self.fps_cap()
        return sorted({f for f in FPS_LIST if f <= cap} | {cap})

    def apply_fps(self):
        """Выбирает FPS: «авто» — максимум экрана; ручной выбор не выше возможностей экрана."""
        al = self.fps_allowed()
        cfg = self.cfg
        if cfg.get('fps_auto', True):
            fps = al[-1]
        else:
            want = cfg['fps']
            fps = want if want in al else max([f for f in al if f <= want] or [al[0]])
        self.fps = fps
        if not self.probing:
            self.set_fps(fps)

    def refresh_display(self):
        """Вызывается при возврате в игру: экран/режим энергосбережения могли поменяться."""
        info = android_display_hz()
        if info:
            self.hz = snap_hz(info[1]) or int(round(info[1]))
        self.power_save = android_power_save()
        self.apply_fps()

    def set_fps(self, fps):
        """Частота кадров игры (не выше частоты экрана)."""
        Clock.unschedule(self.update)
        self.cur_fps = fps
        try:
            Clock._max_fps = 0 if self.probing else max(fps, 30)   # 0 = без ограничения (для замера)
        except Exception:
            pass
        Clock.schedule_interval(self.update, 1.0 / fps)

    def say(self, text):
        self.msg_text, self.msg_t = text, 2.2

    def update(self, dt):
        dt = min(dt, 0.05)
        self.clock += dt
        # энергосбережение: на паузе картинка почти не меняется — рисуем реже
        want = min(self.fps, 30) if self.state == 'pause' else self.fps
        if want != self.cur_fps and not self.probing:
            self.set_fps(want)
        if platform == 'android':                   # следим за режимом энергосбережения телефона
            self.pw_t -= dt
            if self.pw_t <= 0:
                self.pw_t = 10.0
                ps = android_power_save()
                if ps != self.power_save:
                    self.power_save = ps
                    self.apply_fps()
                    self.say('Энергосбережение: до 60 FPS' if ps else f'Энергосбережение выкл: {self.fps} FPS')
        self.lan_poll()
        self.msg_t = max(0.0, self.msg_t - dt)
        self.reset_t = max(0.0, self.reset_t - dt)
        if self.state != 'pause':
            self.world(dt)
            if self.state == 'play':
                self.play(dt)
            elif self.state in ('over', 'lan_over'):
                self.over_t += dt
                self.speed = max(0.0, self.speed - 300 * dt)
            elif self.state == 'splash':
                self.splash_t += dt
                if self.splash_t > SPLASH_DUR and (self.hz_ready or self.splash_t > SPLASH_DUR + 2.0):
                    self.to_menu()      # ждём, пока экран просканируется
            elif self.state == 'lan_search':
                self.lan_search_t -= dt
                if self.lan_search_t <= 0 and self.lan:
                    self.lan_search_t = 1.0
                    self.lan.broadcast(f'{LAN_MAGIC}|FIND')
        self.draw()

    def world(self, dt):
        v = self.speed * dt
        self.scroll += v
        self.run_ph += v * 0.14
        for o in self.obs:
            o['x'] -= v
        self.obs = [o for o in self.obs if o['x'] + o['w'] > -6]
        for c in self.coins:
            c['x'] -= v
        self.coins = [c for c in self.coins if c['x'] + COIN_S > -6]
        for c in self.secrets:
            c['x'] -= v
        self.secrets = [c for c in self.secrets if c['x'] + 10 > -6]
        if self.state == 'play':                            # плашки показываем только в забеге
            if self.toast_t > 0:
                self.toast_t -= dt
            elif self.toast_q:
                self.toast, self.toast_t = self.toast_q.pop(0), 4.0     # (заголовок, текст)
        if self.ph > 0 or self.vy > 0:                      # прыжок
            self.vy -= GRAVITY * dt
            self.ph += self.vy * dt
            if self.ph <= 0:
                self.ph, self.vy, self.jumps = 0.0, 0.0, 2
                self.puff(self.px0 + PW / 2, GROUND, 6, DUST, 25)
        self.gap += (self.gap_t - self.gap) * min(1.0, dt * 6)
        self.inv = max(0.0, self.inv - dt)
        self.shake = max(0.0, self.shake - dt)
        self.flash = max(0.0, self.flash - dt)
        for p in self.parts:
            p[0] += p[2] * dt
            p[1] += p[3] * dt
            p[3] -= 180 * dt
            p[4] -= dt
            if p[1] < GROUND:
                p[1], p[3] = GROUND, abs(p[3]) * 0.3
        self.parts = [p for p in self.parts if p[4] > 0]

    def play(self, dt):
        if self.lan and self.lan_peer_addr:                 # LAN-гонка: шлём свою дистанцию сопернику
            self.lan_send_t -= dt
            if self.lan_send_t <= 0:
                self.lan_send_t = 0.2
                self.lan.send(f'{LAN_MAGIC}|POS|{self.dist}', self.lan_peer_addr)
        self.speed = min(MAX_SPEED, self.speed + ACCEL * dt)
        self.dist += self.speed * dt
        if self.mode == 'bot':
            self.bot_step(dt)
        m = self.meters()
        for i, (_, kind, need) in enumerate(ACH):           # достижения за метры
            if kind == 'm' and m >= need and not self.cfg['ach'][i]:
                self.unlock(i)
        if self.meters() >= self.next_coin:                # Snapdragon-монета раз в 1000 м
            self.next_coin += COIN_EVERY
            self.coins.append({'x': self.ww + 8, 'y': COIN_Y})
            self.spawn_t = max(self.spawn_t, 1.8)           # рядом не ставим препятствия
        if m >= self.next_secret:                           # секретный телефон раз в 5000 м
            self.next_secret += SECRET_EVERY
            left = [i for i in SECRET if not self.owned(i)]
            if left:
                self.secrets.append({'x': self.ww + 8, 'y': SECRET_Y, 'skin': random.choice(left)})
                self.spawn_t = max(self.spawn_t, 2.0)
        hx0, hx1 = self.px0, self.px0 + PW
        hy0, hy1 = GROUND + self.ph, GROUND + self.ph + PH
        for c in list(self.coins):
            if hx0 < c['x'] + COIN_S and hx1 > c['x'] and hy0 < c['y'] + COIN_S and hy1 > c['y']:
                self.coins.remove(c)
                self.collect(c)
        for c in list(self.secrets):
            if hx0 < c['x'] + 8 and hx1 > c['x'] and hy0 < c['y'] + 17 and hy1 > c['y']:
                self.secrets.remove(c)
                self.find_secret(c['skin'])
        self.gap_t = min(MAX_GAP, self.gap_t + REGEN * dt)
        self.spawn_t -= dt
        if self.spawn_t <= 0:
            self.spawn()
            k = max(0.0, min(1.0, (self.speed - START_SPEED) / (MAX_SPEED - START_SPEED)))
            lo = 1.0 - 0.3 * k
            self.spawn_t = self.rng.uniform(lo, lo + 0.9)
        if self.ph == 0:
            self.dust_t -= dt
            if self.dust_t <= 0:
                self.puff(self.px0 + 1, GROUND, 1, DUST, 14)
                self.dust_t = 0.09
        if self.inv <= 0:                                   # столкновения
            x0, x1 = self.px0 + 1.3, self.px0 + PW - 1.3
            y0, y1 = GROUND + self.ph + 2.0, GROUND + self.ph + PH - 1.0
            for o in self.obs:
                if (not o['hit'] and x0 < o['x'] + o['w'] - 1 and x1 > o['x'] + 1
                        and y0 < GROUND + o['h'] - 1 and y1 > GROUND):
                    self.hit(o)
                    break

    def bot_step(self, dt):
        """Один шаг «виртуального игрока»: ИИ бежит с тем же разгоном, иногда врезается в
        препятствия (Охотник приближается) и вылетает, когда Охотник его догоняет."""
        if not self.bot_alive:
            return
        self.bot_speed = min(MAX_SPEED, self.bot_speed + ACCEL * dt)
        self.bot_dist += self.bot_speed * dt
        self.bot_gap = min(MAX_GAP, self.bot_gap + REGEN * dt)
        if random.random() < self.bot_rate * dt:
            self.bot_gap -= HIT_PENALTY
            self.bot_speed = max(START_SPEED, self.bot_speed * 0.85)
            if self.bot_gap <= 0:
                self.bot_alive = False
                if self.state == 'play':
                    self.toast_q.append(('ИИ выбыл из гонки!', f'{int(self.bot_dist / 10)} м'))

    def bot_finish(self):
        """Игрок выбыл: доигрываем за ИИ «в уме» и решаем, кто победил."""
        t = 0.0
        while self.bot_alive and self.bot_dist <= self.dist and t < 900:
            self.bot_step(0.1)
            t += 0.1
        self.bot_result = 'win' if self.dist >= self.bot_dist else 'lose'

    def collect(self, c):
        self.cfg['coins'] += 1
        self.cfg['earned'] += 1
        self.puff(c['x'] + COIN_S / 2, c['y'] + COIN_S / 2, 14, (1.0, 0.25, 0.3, 1.0), 60)
        self.sfx('click')
        self.vibrate(30)
        for i, (_, kind, need) in enumerate(ACH):           # достижения за монеты
            if kind == 'c' and self.cfg['earned'] >= need:
                self.unlock(i)
        self.save()

    def find_secret(self, i):
        cfg = self.cfg
        cfg['owned'] = sorted(set(cfg['owned']) | {i})
        self.puff(self.px0 + PW / 2, SECRET_Y + 8, 18, (1.0, 0.85, 0.2, 1.0), 80)
        self.toast_q.append(('Секретный телефон найден!', SKIN_NAMES[i]))
        self.sfx('click')
        self.vibrate(60)
        self.save()

    def unlock(self, i):
        """Открывает достижение и показывает плашку."""
        if self.cfg['ach'][i]:
            return
        self.cfg['ach'][i] = True
        self.toast_q.append(('Достижение получено!', ACH[i][0]))
        self.sfx('click')
        self.save()

    def spawn(self):
        n = self.rng.choices(range(4), weights=(3, 4, 2, 2))[0]
        w, h = OBSTACLES[n]
        # каждое препятствие — случайный скин из всех (у «двух рядом» скины разные)
        self.obs.append({'x': self.ww + 8, 'w': w, 'h': h, 'n': n, 'hit': False,
                         'skins': [random.choice(POOL), random.choice(POOL)]})

    def hit(self, o):
        o['hit'] = True
        self.gap_t -= HIT_PENALTY
        self.inv, self.shake, self.flash = 1.0, 0.3, 0.3
        self.speed = max(START_SPEED, self.speed * 0.85)
        self.puff(self.px0 + PW / 2, GROUND + self.ph + PH / 2, 14, (1.0, 0.8, 0.3, 1.0), 70)
        self.sfx('hit')
        self.vibrate(70)
        if self.gap_t <= 0:
            self.finish()

    def finish(self):
        m = self.meters()
        self.new_best = m > self.cfg['best']
        if self.new_best:
            self.cfg['best'] = m
            self.save()
        self.sfx('over')
        self.vibrate(250)
        if self.lan and self.lan_peer_addr:                 # играем по сети — особый экран итога
            self.lan.send(f'{LAN_MAGIC}|DEAD|{self.dist}', self.lan_peer_addr)
            self.state, self.over_t, self.shake = 'lan_over', 0.0, 0.5
            if self.lan_peer_alive:
                self.lan_result = 'wait'                     # ждём, пока соперник тоже доедет
            else:
                self.lan_result = 'win' if self.dist >= self.lan_peer_dist else 'lose'
        else:
            if self.mode == 'bot':
                self.bot_finish()
            self.state, self.over_t, self.shake = 'over', 0.0, 0.5

    def puff(self, x, y, n, col, power):
        for _ in range(n):
            life = random.uniform(0.25, 0.6)
            self.parts.append([x, y, random.uniform(-power, power) - self.speed * 0.3,
                               random.uniform(0, power), life, random.uniform(0.8, 1.8), col, life])

    # ---------- примитивы рисования (в единицах мира) ----------
    def sx(self, x):
        return self.x + x * self.s + self.jx

    def sy(self, y):
        return self.y + self.oy + y * self.s + self.jy

    def rect(self, x, y, w, h, col, rad=0.0):
        Color(col[0], col[1], col[2], col[3] * self.alpha)
        pos, size = (self.sx(x), self.sy(y)), (w * self.s, h * self.s)
        rad = min(rad, w / 2, h / 2)
        if rad > 0:
            RoundedRectangle(pos=pos, size=size, radius=[rad * self.s])
        else:
            Rectangle(pos=pos, size=size)

    def dot(self, cx, cy, r, col):
        Color(col[0], col[1], col[2], col[3] * self.alpha)
        Ellipse(pos=(self.sx(cx - r), self.sy(cy - r)), size=(2 * r * self.s, 2 * r * self.s))

    def line(self, pts, w, col):
        Color(col[0], col[1], col[2], col[3] * self.alpha)
        flat = []
        for qx, qy in pts:
            flat += [self.sx(qx), self.sy(qy)]
        Line(points=flat, width=max(1.0, w * self.s))

    def tex(self, msg, px):
        key = (msg, px)
        t = self.tex_cache.get(key)
        if t is None:
            if len(self.tex_cache) > 150:
                self.tex_cache.clear()
            lab = CoreLabel(text=msg, font_size=px, bold=True)
            lab.refresh()
            t = self.tex_cache[key] = lab.texture
        return t

    def text(self, msg, x, y, size, col=(1, 1, 1, 1), anchor='c'):
        t = self.tex(msg, max(8, int(size * self.s)))
        w, h = t.size
        left = self.sx(x) - (0 if anchor == 'l' else w if anchor == 'r' else w / 2)
        if self.cfg['bg'] != 1:                             # светлые фоны: тень для читаемости
            Color(0, 0, 0, 0.5 * col[3] * self.alpha)
            Rectangle(texture=t, pos=(int(left) + max(1, self.s * 0.3), int(self.sy(y) - h / 2) - max(1, self.s * 0.3)),
                      size=(w, h))
        Color(col[0], col[1], col[2], col[3] * self.alpha)
        Rectangle(texture=t, pos=(int(left), int(self.sy(y) - h / 2)), size=(w, h))

    def button(self, name, label, x, y, w, h, col=NAVY, size=5.5, hl=False):
        """Кнопка: рисуется и запоминается для нажатий."""
        self.btns.append((name, x, y, w, h))
        r = min(h * 0.35, 4)
        self.rect(x, y, w, h, col, r)
        Color(*((1, 0.22, 0.45, 1) if hl else (1, 1, 1, 0.22)))
        Line(rounded_rectangle=(self.sx(x), self.sy(y), w * self.s, h * self.s, r * self.s),
             width=max(1.0, self.s * (0.5 if hl else 0.25)))
        if label:
            self.text(label, x + w / 2, y + h / 2, size)

    # ---------- скины ----------
    def smile(self, i, rx, ry, rw, rh):
        """Улыбка с зубами поверх камер скина i. rx, ry, rw, rh — рамка скина в пикселях."""
        t = self.smile_tex
        if not t:
            return
        fx, fy, fw = SKINS[i][2]
        fw = min(fw * 1.3, 2 * min(fx, 1 - fx))             # не шире самого телефона
        w = fw * rw
        h = w * t.height / t.width
        Color(1, 1, 1, self.alpha)
        Rectangle(texture=t, pos=(rx + fx * rw - w / 2, ry + (1 - fy) * rh - h / 2), size=(w, h))

    def skin(self, i, x, y, w, h, grin=False, rot=False):
        """Фото телефона (скин) в рамке x,y,w,h; grin — улыбка с зубами на камерах."""
        t = self.pics.get(i)
        if t:
            Color(1, 1, 1, self.alpha)
            if rot:                                         # лежит на боку: поворот на 90°
                cx, cy = self.sx(x + w / 2), self.sy(y + h / 2)
                rx, ry, rw, rh = cx - h * self.s / 2, cy - w * self.s / 2, h * self.s, w * self.s
                PushMatrix()
                Rotate(angle=90, origin=(cx, cy))
                Rectangle(texture=t, pos=(rx, ry), size=(rw, rh))
                if grin:
                    self.smile(i, rx, ry, rw, rh)
                PopMatrix()
            else:
                rx, ry, rw, rh = self.sx(x), self.sy(y), w * self.s, h * self.s
                Rectangle(texture=t, pos=(rx, ry), size=(rw, rh))
                if grin:
                    self.smile(i, rx, ry, rw, rh)
        else:
            self.rect(x, y, w, h, (0.5, 0.5, 0.55, 1), w * 0.2)

    def coin(self, x, y, size, bob=True):
        """Snapdragon-монета (логотип без фона) с красным свечением."""
        y += math.sin(self.clock * 4 + x * 0.1) * 1.2 if bob else 0.0
        if bob:
            self.dot(x + size / 2, y + size / 2, size * 0.85, (1.0, 0.2, 0.3, 0.22))
        if self.coin_tex:
            Color(1, 1, 1, self.alpha)
            Rectangle(texture=self.coin_tex, pos=(self.sx(x), self.sy(y)),
                      size=(size * self.s, size * self.s))
        else:
            self.rect(x, y, size, size, (0.15, 0.15, 0.17, 1), size * 0.2)

    def runner(self, x, y, w, h, leg, skin, grin, air=False):
        """Скин с бегущими ножками."""
        for i, hx in enumerate((x + w * 0.3, x + w * 0.7)):
            a = self.run_ph + i * math.pi
            fx = hx if air else hx + math.sin(a) * w * 0.22
            fy = y + (leg * 0.45 if air else max(0.0, math.cos(a)) * leg * 0.45)
            self.line([(hx, y + leg), (fx, fy)], w * 0.13, (0.85, 0.87, 0.95, 1))
        self.skin(skin, x, y + leg, w, h - leg, grin)

    # ---------- кадр ----------
    def draw(self):
        self.canvas.clear()
        if self.shake > 0:
            m = self.shake * 2.2 * self.s
            self.jx, self.jy = random.uniform(-m, m), random.uniform(-m, m)
        else:
            self.jx = self.jy = 0.0
        with self.canvas:
            if self.state == 'splash':
                self.draw_splash()
            else:
                self.draw_back()
                self.draw_actors()
                self.jx = self.jy = 0.0
                self.draw_ui()

    def draw_back(self):
        bg = self.cfg['bg']
        th = BG_THEME[bg]
        s, ww = self.s, self.ww
        n = 8
        for i in range(n):                                  # небо
            k = i / (n - 1)
            Color(*[th['top'][j] + (th['bot'][j] - th['top'][j]) * k for j in range(3)], 1)
            Rectangle(pos=(self.x, self.y + self.height * (1 - (i + 1) / n)),
                      size=(self.width, self.height / n + 1))
        if bg == 0:
            self.back_desert()
        elif bg == 1:
            self.back_city()
        elif bg == 2:
            self.back_forest()
        elif bg == 3:
            self.back_ruins()
        else:
            self.back_moscow()
        Color(*th['road'], 1)                               # дорога
        Rectangle(pos=(self.x, self.y), size=(self.width, self.sy(GROUND) - self.y))
        self.rect(-5, GROUND - 1.2, ww + 10, 1.2, (*th['edge'], 1))
        k = -(self.scroll % 26.0)
        while k < ww:
            self.rect(k, 10, 12, 1.1, (*th['dash'], 1))
            k += 26.0

    def back_desert(self):
        ww = self.ww
        self.dot(ww * 0.78, 74, 14, (1, 0.95, 0.6, 0.25))   # солнце
        self.dot(ww * 0.78, 74, 9, (1, 0.97, 0.7, 1))
        self.layer(self.dunes_far, 0.06, lambda x, rx, ry: self.oval(x, GROUND, rx, ry + 10, (0.93, 0.66, 0.38, 1)))
        self.layer(self.dunes_near, 0.16, lambda x, rx, ry: self.oval(x, GROUND, rx, ry + 3, (0.80, 0.53, 0.29, 1)))

        def cactus(x, h, two):
            col = (0.22, 0.45, 0.24, 1)
            self.rect(x, GROUND - 1, 2.6, h, col, 1.3)
            self.rect(x - 3.2, GROUND + h * 0.35, 1.8, 5, col, 0.9)
            self.rect(x - 3.2, GROUND + h * 0.35, 3.6, 1.8, col, 0.9)
            if two:
                self.rect(x + 4.0, GROUND + h * 0.55, 1.8, 4.5, col, 0.9)
                self.rect(x + 2.2, GROUND + h * 0.55, 3.6, 1.8, col, 0.9)
        self.layer(self.cacti, 0.45, cactus)

    def back_city(self):
        s, ww = self.s, self.ww
        Color(1, 1, 1, 0.8)                                 # звёзды
        pts = []
        for fx, fy in self.stars:
            pts += [self.x + fx * self.width, self.sy(fy * WORLD_H)]
        Point(points=pts, pointsize=max(1.0, s * 0.2))
        if self.state in ('menu', 'play', 'pause', 'over'):
            self.dot(ww * 0.85, 80, 7.5, (1, 0.96, 0.75, 0.15))  # луна
            self.dot(ww * 0.85, 80, 5.5, (1, 0.96, 0.8, 1))
        off = -((self.scroll * 0.18) % self.city_w)         # город (медленнее дороги)
        lit, neon = [], ((0.2, 0.95, 1.0, 0.85), (1.0, 0.25, 0.6, 0.85), (0.7, 0.4, 1.0, 0.85))
        for rep in (0, 1):
            for bx, bw, bh, wins in self.city:
                x = off + rep * self.city_w + bx
                if x > ww or x + bw < 0:
                    continue
                self.rect(x, GROUND - 1, bw, bh + 1, (0.10, 0.11, 0.27, 1))
                self.rect(x, GROUND + bh - 0.5, bw, 0.7, neon[int(bw * 10) % 3])   # неоновая кромка
                for wx, wy in wins:
                    lit += [self.sx(x + wx), self.sy(GROUND + wy)]
        if lit:
            Color(1, 0.85, 0.45, 0.55)
            Point(points=lit, pointsize=max(1.0, s * 0.8))

    def back_ruins(self):
        """Заброшка: туманные руины, мёртвые деревья, сетчатый забор."""
        ww = self.ww
        self.dot(ww * 0.78, 76, 11, (0.95, 0.97, 0.9, 0.18))         # бледное солнце сквозь дымку
        self.dot(ww * 0.78, 76, 6, (0.97, 0.98, 0.92, 0.75))

        def ruin(x, w, h, seed, col):
            self.rect(x, GROUND - 1, w, h + 1, col)
            top = (col[0] * 0.8, col[1] * 0.8, col[2] * 0.8, 1)
            self.tri(x, GROUND + h, w * 0.45, 3 + seed * 5, col)         # обвалившаяся крыша
            self.rect(x + w * 0.55, GROUND + h - 3 - seed * 4, w * 0.45, 3 + seed * 4, top)
            hole = (0.05, 0.06, 0.07, 1)                                  # чёрные окна
            for wx in range(2, int(w) - 2, 5):
                for wy in range(4, int(h) - 3, 7):
                    if (wx * 7 + wy * 3 + int(seed * 10)) % 3:
                        self.rect(x + wx, GROUND + wy, 2.2, 3.2, hole)
        self.layer(self.ruins_far, 0.14, lambda x, w, h, sd: ruin(x, w, h, sd, (0.43, 0.48, 0.45, 1)))
        self.layer(self.ruins_near, 0.30, lambda x, w, h, sd: ruin(x, w, h, sd, (0.22, 0.25, 0.25, 1)))

        def dead_tree(x, h, bent):
            col = (0.10, 0.10, 0.11, 1)
            self.rect(x, GROUND - 1, 1.3, h, col)
            d = 1 if bent else -1
            self.line([(x + 0.6, GROUND + h * 0.55), (x + 0.6 + 5 * d, GROUND + h * 0.8)], 0.7, col)
            self.line([(x + 0.6, GROUND + h * 0.75), (x + 0.6 - 4 * d, GROUND + h * 0.95)], 0.6, col)
            self.line([(x + 0.6, GROUND + h * 0.4), (x + 0.6 - 3.5 * d, GROUND + h * 0.58)], 0.5, col)
        self.layer(self.dead_trees, 0.5, dead_tree)

        def post(x, broken):                                              # забор из сетки
            col = (0.12, 0.13, 0.13, 1)
            self.rect(x, GROUND - 1, 0.7, 6 if broken else 9, col)
            self.rect(x, GROUND + 5.5, 5.0, 0.35, col)
            if not broken:
                self.rect(x, GROUND + 2.5, 5.0, 0.35, col)
        self.layer(self.fence, 0.7, post)
        Color(0.75, 0.8, 0.75, 0.10)                                     # туман у земли
        Rectangle(pos=(self.x, self.sy(GROUND)), size=(self.width, 22 * self.s))

    def back_moscow(self):
        """Москва: Сити, Останкинская башня, Кремль и собор Василия Блаженного на закате."""
        ww = self.ww
        self.dot(ww * 0.80, 40, 16, (1.0, 0.75, 0.45, 0.30))           # низкое закатное солнце
        self.dot(ww * 0.80, 40, 9, (1.0, 0.88, 0.62, 1))
        self.layer(self.msk_city, 0.08, lambda x, w, h, spire: (
            self.rect(x, GROUND - 1, w, h + 1, (0.22, 0.22, 0.42, 1)),
            self.tri(x + w * 0.25, GROUND + h, w * 0.5, 7, (0.22, 0.22, 0.42, 1)) if spire else None))

        def ostankino(x):
            col = (0.17, 0.17, 0.34, 1)
            self.tri(x - 3.5, GROUND - 1, 7, 24, col)
            self.rect(x - 0.8, GROUND + 20, 1.6, 40, col)
            self.rect(x - 3.5, GROUND + 33, 7, 3.2, col)                # смотровая площадка
            self.rect(x - 0.2, GROUND + 60, 0.4, 12, col)
        self.layer(self.ostankino, 0.12, ostankino)

        brick, roof, gold = (0.62, 0.17, 0.15, 1), (0.13, 0.45, 0.30, 1), (0.95, 0.78, 0.25, 1)

        def wall(x, w):
            self.rect(x, GROUND - 1, w, 10, brick)
            mx = 0.0
            while mx < w - 1:                                          # зубцы «ласточкин хвост»
                self.rect(x + mx, GROUND + 9, 1.8, 1.8, brick)
                mx += 3.2

        def tower(x, w, h, clock=False):
            self.rect(x, GROUND - 1, w, h + 1, brick)
            self.rect(x - 1, GROUND + h, w + 2, 1.6, (0.50, 0.12, 0.11, 1))
            self.tri(x - 0.5, GROUND + h + 1.6, w + 1, w * 1.7, roof)
            self.dot(x + w / 2, GROUND + h + 1.6 + w * 1.7 + 1.2, 1.1, (1, 0.15, 0.15, 1))   # звезда
            if clock:
                self.dot(x + w / 2, GROUND + h - 6, 2.3, (0.97, 0.95, 0.85, 1))             # часы
                self.dot(x + w / 2, GROUND + h - 6, 0.5, (0.1, 0.1, 0.1, 1))

        def basil(x, w):
            self.rect(x, GROUND - 1, w, 12, (0.70, 0.30, 0.22, 1))
            self.rect(x + w / 2 - 3, GROUND + 11, 6, 10, (0.78, 0.45, 0.3, 1))
            self.tri(x + w / 2 - 3.4, GROUND + 21, 6.8, 11, (0.20, 0.55, 0.35, 1))        # центральный шатёр
            self.dot(x + w / 2, GROUND + 33, 0.9, gold)
            for k, (dx, col) in enumerate(((5, (0.9, 0.25, 0.2, 1)), (13, (0.2, 0.55, 0.85, 1)),
                                           (w - 13, (0.95, 0.75, 0.2, 1)), (w - 5, (0.2, 0.65, 0.35, 1)))):
                hgt = 12 + (k % 2) * 3
                self.rect(x + dx - 2, GROUND + 11, 4, hgt - 7, (0.78, 0.45, 0.3, 1))      # барабан
                self.oval(x + dx, GROUND + hgt + 1, 3.2, 4.2, col)                         # луковка
                self.tri(x + dx - 0.7, GROUND + hgt + 4.5, 1.4, 2.2, gold)

        def kremlin(x, kind, w, h):
            if kind == 'wall':
                wall(x, w)
            elif kind == 'tower':
                tower(x, w, h)
            elif kind == 'spasskaya':
                tower(x, w, h, True)
            else:
                basil(x, w)
        self.layer(self.kremlin, 0.30, kremlin)

    def back_forest(self):
        ww = self.ww
        self.dot(ww * 0.8, 76, 12, (1, 0.98, 0.8, 0.3))     # солнце
        self.dot(ww * 0.8, 76, 7.5, (1, 0.99, 0.88, 1))
        self.layer(self.clouds, 0.04, lambda x, y, r: (self.oval(x, y, r, r * 0.32, (1, 1, 1, 0.75)),
                                                       self.oval(x + r * 0.4, y + r * 0.2, r * 0.6, r * 0.3, (1, 1, 1, 0.75))))
        self.layer(self.hills, 0.07, lambda x, rx, ry: self.oval(x, GROUND, rx, ry + 8, (0.40, 0.65, 0.52, 1)))

        def tree(x, h, shade, trunk=(0.30, 0.20, 0.12, 1), base=0.55):
            g = (0.10 * shade, 0.40 * shade, 0.18 * shade, 1)
            w = h * 0.55
            self.rect(x - h * 0.04, GROUND - 1, h * 0.08, h * 0.25, trunk)
            for j in range(3):                              # три яруса ёлки
                ww_ = w * (1 - j * 0.27)
                self.tri(x - ww_ / 2, GROUND + h * (0.18 + j * 0.27), ww_, h * 0.42, g)
        self.layer(self.trees_far, 0.22, lambda x, h, sh: tree(x, h, sh * 0.75))
        self.layer(self.trees_near, 0.5, tree)

    def draw_actors(self):
        s, cfg = self.s, self.cfg
        for o in self.obs:                                  # препятствия
            self.alpha = 0.3 if o['hit'] else 1.0
            a, b = o['skins']
            if o['n'] == 3:
                self.skin(a, o['x'], GROUND, 12, 23, True)
                self.skin(b, o['x'] + 12, GROUND, 12, 23, True)
            else:
                self.skin(a, o['x'], GROUND, o['w'], o['h'], True, o['n'] == 0)
        self.alpha = 1.0
        for c in self.coins:                                # Snapdragon-монеты
            self.coin(c['x'], c['y'], COIN_S)
        for c in self.secrets:                              # секретные телефоны
            by = c['y'] + math.sin(self.clock * 4 + c['x'] * 0.1) * 1.2
            self.dot(c['x'] + 4, by + 8.5, 11, (1.0, 0.85, 0.2, 0.22))
            self.skin(c['skin'], c['x'], by, 8, 17, True)
        if self.mode == 'bot' and self.state in ('play', 'pause'):      # ИИ — полупрозрачный бегун
            bx = self.px0 + (self.bot_dist - self.dist) / 10 * 1.4
            if -12 < bx < self.ww:
                self.alpha = 0.5 if self.bot_alive else 0.25
                self.runner(bx, GROUND, PW, PH, P_LEG, self.bot_skin, False)
                self.alpha = 1.0
                self.text('ИИ', bx + PW / 2, GROUND + PH + 3, 3.6, (1, 0.85, 0.3, 1))
        cx = self.px0 - self.gap - CW                       # охотник
        self.runner(cx, GROUND, CW, CH, C_LEG, cfg['hunter'], True)
        k = max(0.35, 1 - self.ph / 60)                     # тень героя
        Color(0, 0, 0, 0.35)
        Ellipse(pos=(self.sx(self.px0 + PW / 2) - PW * k * s * 0.7, self.sy(GROUND - 1.6)),
                size=(PW * k * s * 1.4, 1.8 * s))
        blink = self.inv > 0 and int(self.clock * 16) % 2 == 0
        self.alpha = 0.3 if blink else 1.0                  # мигает после удара
        self.runner(self.px0, GROUND + self.ph, PW, PH, P_LEG, cfg['hero'], False, self.ph > 0.3)
        self.alpha = 1.0
        for p in self.parts:
            self.rect(p[0], p[1], p[5], p[5], (p[6][0], p[6][1], p[6][2], max(0.0, p[4] / p[7])))

    def title(self, c, y):
        for dx, dy, col in ((-0.6, -0.5, (0.1, 0.9, 0.95, 1)), (0.6, 0.5, (1, 0.2, 0.45, 1)),
                            (0, 0, (1, 1, 1, 1))):
            self.text('TechTok run', c + dx, y + dy, 12, col)

    def draw_splash(self):
        """Заставка при запуске: название проявляется из темноты; пропустить нельзя (идёт проверка экрана)."""
        Color(0, 0, 0, 1)
        Rectangle(pos=self.pos, size=self.size)
        t = self.splash_t
        fade = min(1.0, t / 1.6)
        self.alpha = fade
        self.title(self.ww / 2, WORLD_H / 2)
        self.alpha = 1.0
        if t > 1.0:
            a = min(1.0, (t - 1.0) * 1.5)
            msg = (f'Экран: {self.hz} Гц · {self.fps} FPS' if self.hz_ready else 'Проверяем экран...')
            self.text(msg, self.ww / 2, WORLD_H / 2 - 16, 3.8, (1, 1, 1, 0.6 * a))

    def draw_ui(self):
        c, st, cfg = self.ww / 2, self.state, self.cfg
        self.btns = []
        if self.flash > 0:
            Color(1, 0.15, 0.1, min(0.5, self.flash * 1.2))
            Rectangle(pos=self.pos, size=self.size)
        if st == 'pause':
            Color(0, 0, 0, 0.55)
            Rectangle(pos=self.pos, size=self.size)
        elif st in ('settings', 'skins', 'ach', 'lan_menu', 'lan_wait', 'lan_search', 'play_modes', 'upgrades') and cfg['bg'] != 1:
            Color(0, 0, 0, 0.35)                            # затемнение светлых фонов под меню
            Rectangle(pos=self.pos, size=self.size)
        if self.height > self.width:                        # вертикальный режим
            self.text('Поверни телефон горизонтально', c, WORLD_H + self.oy / self.s / 2, 5.5,
                      (1, 0.9, 0.4, 1))
        if st in ('play', 'pause'):
            self.text(f'{self.meters()} м', 4, 90, 8, anchor='l')
            if self.mode == 'bot':
                self.text(f'ИИ: {int(self.bot_dist / 10)} м' + ('' if self.bot_alive else ' (выбыл)'),
                          4, 70, 4.2, (1, 0.85, 0.3, 1) if self.bot_alive else (1, 0.5, 0.4, 1), 'l')
            if self.lan:
                self.text(f'Соперник: {int(self.lan_peer_dist / 10)} м', self.ww - 14, 91, 4,
                          (1, 0.8, 0.3, 0.9), 'r')
            else:
                self.text(f'Рекорд {cfg["best"]} м', self.ww - 14, 91, 4, (1, 1, 1, 0.7), 'r')
            self.coin(4, 76, 6.5, False)                    # счётчик монет
            self.text(str(cfg['coins']), 12, 79.3, 5.5, anchor='l')
            ratio = max(0.0, min(1.0, self.gap / MAX_GAP))   # шкала дистанции до охотника
            self.rect(c - 28, 89, 56, 3.4, (0, 0, 0, 0.45), 1.7)
            self.rect(c - 28, 89, 56 * ratio, 3.4,
                      (min(1.0, 2 * (1 - ratio)), min(1.0, 2 * ratio), 0.2, 1), 1.7)
            self.text('дистанция до охотника', c, 96, 3.7, (1, 1, 1, 0.8))
            bx = self.ww - 11                               # значок паузы
            self.btns.append(('pause', bx - 1, 86, 10, 10))
            self.rect(bx, 87, 8, 8, (0, 0, 0, 0.45), 2)
            Color(1, 1, 1, 1)
            if st == 'play':
                self.rect(bx + 2.2, 88.8, 1.3, 4.4, (1, 1, 1, 1))
                self.rect(bx + 4.6, 88.8, 1.3, 4.4, (1, 1, 1, 1))
            else:
                Triangle(points=[self.sx(bx + 2.8), self.sy(88.6), self.sx(bx + 2.8),
                                 self.sy(93.4), self.sx(bx + 6.2), self.sy(91)])
        if st == 'menu':
            self.title(c, 82)
            self.skin(self.menu_obs, self.ww * 0.74, GROUND, 15, 32, True)
            self.coin(4, 86, 6.5, False)
            self.text(str(cfg['coins']), 12, 89.3, 5.5, anchor='l')
            self.button('play', 'Играть', c - 30, 60, 60, 10, PINK, hl=True)
            self.button('skins', 'Скины', c - 30, 47, 60, 10)
            self.button('upgrades', 'Улучшения', c - 30, 34, 60, 10)
            self.button('ach', 'Достижения', c - 30, 21, 60, 10)
            self.button('settings', 'Настройки', c - 30, 8, 60, 10)
        elif st == 'play_modes':
            self.text('Выбери режим', c, 88, 8)
            self.button('mode_lan', 'Игра по сети (локальная сеть)', c - 54, 66, 108, 12, NAVY, 4.3)
            self.text('Гонка с другом по Wi-Fi', c, 62, 3.2, (1, 1, 1, 0.65))
            self.button('mode_single', 'Играть (одиночная)', c - 54, 46, 108, 12, PINK, 4.5, hl=True)
            self.text('Обычный забег на рекорд', c, 42, 3.2, (1, 1, 1, 0.65))
            self.button('mode_bot', 'Играть с ботами (ИИ)', c - 54, 26, 108, 12, NAVY, 4.5)
            self.text('Гонка с ИИ: кто пробежит дальше', c, 22, 3.2, (1, 1, 1, 0.65))
            self.button('back', 'Назад', c - 30, 5, 60, 11)
        elif st == 'upgrades':
            self.text('Улучшения', c, 90, 8)
            self.coin(c - 28, 78, 5.5, False)
            self.text(f'Снапы: {cfg["coins"]}', c - 20, 80.5, 4.6, anchor='l')
            for j, (key, name, desc, btn) in enumerate((
                    ('jump_level', 'Прыжок', 'Прыжок выше (+3,5% за уровень)', 'upgrade_jump'),
                    ('run_level', 'Бег', 'Быстрее старт забега (+2,5% за уровень)', 'upgrade_run'))):
                y = 52 - j * 26
                lvl = cfg.get(key, 0)
                done = lvl >= UPGRADE_MAX
                can = cfg['coins'] >= UPGRADE_PRICE
                self.button(btn, f'{name} {lvl}/{UPGRADE_MAX} · ' + ('МАКС' if done else f'{UPGRADE_PRICE} снапа'),
                            c - 52, y, 104, 13, NAVY if done else (GREEN if can else (0.35, 0.35, 0.4, 0.95)),
                            4.6, hl=not done and can)
                for k in range(UPGRADE_MAX):                # три деления уровня
                    self.rect(c - 52 + k * 35, y - 4.5, 33, 2.2, PINK if k < lvl else (0, 0, 0, 0.45), 1.1)
                self.text(desc, c, y + 20, 3.7, (1, 1, 1, 0.85))
            self.button('back', 'Назад', c - 30, 6, 60, 11)
        elif st == 'settings':
            self.text('Настройки', c, 90, 8)
            bw = min(76.0, (self.ww - 12) / 2 - 2)
            lx, rx = c - bw - 2, c + 2
            for i, (key, name) in enumerate((('vibro', 'Вибрация'), ('sound', 'Звук'))):
                on = cfg[key]
                self.button(key, f'{name}: {"Вкл" if on else "Выкл"}', lx, 68 - i * 17, bw, 13,
                            GREEN if on else NAVY, 4.6)
            locked = len(self.fps_allowed()) < 2
            self.button('fps', f'Кадры: {self.fps} FPS' + (' (макс.)' if locked else ''), rx, 68, bw, 13,
                        (0.30, 0.31, 0.37, 1) if locked else NAVY, 4.6)
            self.text(f'Экран {self.hz} Гц' + (' · энергосбережение: до 60 FPS' if self.power_save else ''),
                      c, 11, 3.2, (1, 1, 1, 0.7))
            self.button('bg', f'Фон: {BG_NAMES[cfg["bg"]]}', rx, 51, bw, 13, NAVY, 4.6)
            armed = self.reset_t > 0
            self.button('reset', 'Точно сбросить?' if armed else 'Сброс прогресса', lx, 34, bw, 13,
                        (0.75, 0.15, 0.2, 1) if armed else NAVY, 4.6)
            self.button('code', 'Код разработчика', rx, 34, bw, 13, NAVY, 4.6)
            self.button('promo', 'Промокоды', lx, 17, bw, 13, NAVY, 4.6)
            self.button('back', 'Назад', rx, 17, bw, 13)
        elif st == 'skins':
            tw = min(48.0, (self.ww - 60) / 2)
            x0 = c - (2 * tw + 4) / 2
            for i, name in enumerate(TABS):                 # кого одеваем: охотника или героя
                self.button(f'tab{i}', name, x0 + i * (tw + 4), 88, tw, 10,
                            PINK if self.tab == i else NAVY, 4)
            self.coin(2, 87, 7, False)                      # монеты игрока
            self.text(str(cfg['coins']), 10.5, 90.5, 5.5, anchor='l')
            sw = min(40.0, (self.ww - 12) / len(SECTIONS) - 2)
            sx0 = c - (len(SECTIONS) * sw + (len(SECTIONS) - 1) * 2) / 2
            for b, name in enumerate(SECTIONS):             # вкладки: Samsung / Магазин
                self.button(f'sec{b}', name, sx0 + b * (sw + 2), 76, sw, 9,
                            PINK if self.brand == b else NAVY, 3.6)
            key, ids = KEYS[self.tab], self.cur_ids()
            picker = self.brand == 1 and self.shop_brand is None
            if picker:                                      # кнопки брендов
                cols = 4
                bw2 = min(46.0, (self.ww - 12) / cols - 2)
                bx0 = c - (cols * bw2 + (cols - 1) * 2) / 2
                for k, br in enumerate(SHOP_BRANDS):
                    ids_b = [i for i in SHOP if SKINS[i][1] == br]
                    have = sum(self.owned(i) for i in ids_b)
                    self.button(f'shb{k}', f'{br} {have}/{len(ids_b)}', bx0 + (k % cols) * (bw2 + 2),
                                60 - (k // cols) * 14, bw2, 12, NAVY, min(3.6, bw2 * 0.085))
            cw = min(36.0, (self.ww - 12) / PER_PAGE - 3)
            pages = (len(ids) + PER_PAGE - 1) // PER_PAGE
            first = self.page * PER_PAGE
            cnt = min(PER_PAGE, len(ids) - first)
            x1 = c - (cnt * cw + (cnt - 1) * 3) / 2
            for j in range(cnt):
                i = ids[first + j]
                x, cx = x1 + j * (cw + 3), x1 + j * (cw + 3) + cw / 2
                ok = self.owned(i)
                hidden = not ok and i in SECRET             # ненайденный секрет: серая карточка
                self.button(f'skin{i}', '', x, 22, cw, 50, (0.42, 0.43, 0.48, 0.95) if hidden else NAVY,
                            hl=(ok and cfg[key] == i) or self.pending == i)
                ih = min(34.0, (cw - 4) / 0.47)
                self.alpha = 1.0 if ok else 0.5
                if not hidden:
                    self.skin(i, x + (cw - ih * 0.47) / 2, 33, ih * 0.47, ih, self.tab == 0)
                self.alpha = 1.0
                self.text(SKINS[i][1] if ok or i not in SECRET else '???', cx, 29, min(3.2, cw * 0.11))   # только бренд
                if i in SHOP_TIER:                          # редкость телефона
                    self.text(RARITY_NAMES[SHOP_TIER[i]], cx, 24.5, min(2.8, cw * 0.095), (1, 1, 1, 0.75))
                if not ok and i in SECRET:
                    self.text('?', cx, 49, 34, (1, 1, 1, 0.85))
                    self.text('раз в 5000 м', cx, 34, min(3.5, cw * 0.11), (1, 1, 1, 0.85))
                elif not ok:                                  # цена в монетах Snapdragon
                    self.rect(cx - 7.5, 40.5, 15, 8, (0, 0, 0, 0.7), 2)
                    self.coin(cx - 6.5, 41.7, 5.6, False)
                    self.text(str(price(i)), cx + 0.5, 44.8, 4.6, (1, 0.9, 0.4, 1), 'l')
                elif self.brand > 0:                        # куплено/найдено — зелёная галочка
                    self.line([(x + cw - 7, 66.5), (x + cw - 5.5, 65), (x + cw - 2.8, 68.3)],
                              0.9, (0.3, 0.95, 0.6, 1))
            self.button('back', 'К брендам' if self.brand == 1 and not picker else 'Назад', 4, 4, 34, 11)
            if pages > 1:
                self.button('prev', '<', 41, 4, 12, 11, PINK, 6)
                self.text(f'{self.page + 1}/{pages}', 59, 9.5, 4.2)
                self.button('next', '>', 66, 4, 12, 11, PINK, 6)
            if self.pending is not None and not self.owned(self.pending):
                p = 0 if cfg['free_pick'] > 0 else price(self.pending)
                can = cfg['coins'] >= p
                self.button('buy', 'Взять бесплатно' if p == 0 else f'Купить за {p}', self.ww - 66, 4, 62, 11,
                            GREEN if can else (0.35, 0.35, 0.4, 0.95), 4.4, hl=can)
            elif self.brand == 2:
                self.text(f'Найдено {sum(self.owned(i) for i in SECRET)}/{len(SECRET)} · выпадают в забеге',
                          self.ww - 4, 9.5, 3.6, (1, 0.9, 0.4, 0.95), 'r')
            elif self.brand == 1:
                self.text('Выбери бренд' if picker else 'Выбери телефон — от простых к редким', self.ww - 4, 9.5, 3.6, (1, 0.9, 0.4, 0.95), 'r')
        elif st == 'ach':
            self.text('Достижения', c, 90, 8)
            rw = min(160.0, self.ww - 16)
            rx = c - rw / 2
            for i, (name, kind, need) in enumerate(ACH):
                y, done = 66 - i * 16, cfg['ach'][i]
                have = need if done else min(need, cfg['best'] if kind == 'm' else cfg['earned'])
                self.rect(rx, y, rw, 14, GREEN if done else NAVY, 3)
                self.rect(rx + 3, y + 5, 8, 6.5, (1, 1, 1, 0.9 if done else 0.15), 2)
                if done:                                    # галочка
                    self.line([(rx + 4.2, y + 8.3), (rx + 6.2, y + 6.4), (rx + 9.8, y + 10.4)],
                              0.9, (0.05, 0.4, 0.3, 1))
                self.text(name, rx + 15, y + 9.8, 4.2, anchor='l')
                self.text(f'{have} / {need}', rx + rw - 3, y + 9.8, 3.9, (1, 1, 1, 0.9), 'r')
                self.rect(rx + 15, y + 2.2, rw - 18, 2.2, (0, 0, 0, 0.4), 1.1)
                if have > 0:
                    self.rect(rx + 15, y + 2.2, (rw - 18) * have / need, 2.2, PINK, 1.1)
            self.button('back', 'Назад', c - 30, 4, 60, 11)
        elif st == 'lan_menu':
            self.text('Игра по сети', c, 86, 7.5)
            self.text('Оба телефона должны быть в одном Wi-Fi', c, 76, 3.9, (1, 1, 1, 0.85))
            self.button('lan_host', 'Создать комнату', c - 62, 46, 60, 16, PINK, 4.6)
            self.button('lan_search', 'Найти комнату', c + 2, 46, 60, 16, NAVY, 4.6)
            self.button('back', 'Назад', c - 30, 10, 60, 11)
        elif st == 'lan_wait':
            self.text('Комната создана', c, 80, 7)
            self.text(f'Код: {self.lan_code}', c, 64, 10, (1, 0.9, 0.4, 1))
            self.text('Ждём, пока соперник найдёт комнату в этой же Wi-Fi...', c, 48, 3.6,
                      (1, 1, 1, 0.8))
            self.button('lan_cancel', 'Отмена', c - 30, 12, 60, 11)
        elif st == 'lan_search':
            self.text('Поиск комнат...', c, 84, 7)
            rw = min(140.0, self.ww - 20)
            rx = c - rw / 2
            if not self.lan_hosts:
                self.text('Ищем комнаты в этой же Wi-Fi сети...', c, 58, 3.8, (1, 1, 1, 0.75))
            for j, (code, addr) in enumerate(self.lan_hosts[:4]):
                self.button(f'lan_join{j}', f'Комната {code}', rx, 58 - j * 14, rw, 12, NAVY, 4.6)
            self.button('lan_cancel', 'Отмена', c - 30, 8, 60, 11)
        elif st == 'lan_over':
            t = min(1.0, self.over_t * 3)
            self.rect(c - 62, 44, 124, 54, (0, 0, 0, 0.55 * t), 5)
            if self.lan_result == 'wait':
                self.text('Ждём, пока соперник доедет...', c, 82, 5.5, (1, 1, 1, t))
            else:
                win = self.lan_result == 'win'
                self.text('Ты выиграл!' if win else 'Ты проиграл',
                          c, 86, 7, (0.3, 0.95, 0.6, t) if win else (1, 0.4, 0.4, t))
            self.text(f'Ты: {self.meters()} м', c, 70, 5, (1, 1, 1, t))
            self.text(f'Соперник: {int(self.lan_peer_dist / 10)} м', c, 61, 5, (1, 1, 1, t))
            if self.over_t > 0.5:
                self.button('menu', 'В меню', c - 30, 20, 60, 13)
        elif st == 'over':
            t = min(1.0, self.over_t * 3)
            self.rect(c - 62, 44, 124, 54, (0, 0, 0, 0.55 * t), 5)
            if self.mode == 'bot':
                win = self.bot_result == 'win'
                self.text('Ты победил ИИ!' if win else 'ИИ победил', c, 90, 6.5,
                          (0.3, 0.95, 0.6, t) if win else (1, 0.45, 0.4, t))
                self.text(f'Ты: {self.meters()} м  ·  ИИ: {int(self.bot_dist / 10)} м', c, 80, 5, (1, 1, 1, t))
            else:
                self.text('Охотник догнал тебя!', c, 90, 6, (1, 0.55, 0.2, t))
                self.text(f'Дистанция: {self.meters()} м', c, 80, 5.5, (1, 1, 1, t))
            self.text('Новый рекорд!' if self.new_best else f'Рекорд: {cfg["best"]} м',
                      c, 71, 4.6, (1, 0.9, 0.4, t))
            if self.over_t > 0.5:
                self.button('menu', 'В меню', c - 54, 48, 50, 13)
                self.button('again', 'Заново', c + 4, 48, 50, 13, PINK, hl=True)
        elif st == 'pause':
            self.text('Пауза', c, 72, 10)
            self.button('menu', 'В меню', c - 52, 42, 50, 13)
            self.button('again', 'Заново', c + 2, 42, 50, 13, PINK, hl=True)
        if st in ('menu', 'settings', 'skins', 'ach', 'lan_menu', 'lan_wait', 'lan_search', 'play_modes', 'upgrades'):
            self.text(VERSION, self.ww - 3, 2.2 if st == 'skins' else 5, 3.4, (1, 1, 1, 0.85), 'r')
        if self.msg_t > 0:                                  # короткое сообщение (покупка, код...)
            a = min(1.0, self.msg_t * 2)
            self.rect(c - 62, 49, 124, 12, (0.10, 0.11, 0.27, 0.95 * a), 3)
            self.text(self.msg_text, c, 55, 4.2, (1, 1, 1, a))
        if self.toast_t > 0 and st == 'play':               # плашка «достижение получено»
            a = min(1.0, self.toast_t * 2)
            self.rect(c - 55, 56, 110, 15, (0.10, 0.55, 0.42, 0.95 * a), 3)
            self.text(self.toast[0], c, 67.5, 3.7, (1, 1, 1, 0.9 * a))
            self.text(self.toast[1], c, 61.5, 4.6, (1, 1, 1, a))


class TechTokApp(App):
    title = 'TechTok run'

    def build(self):
        if platform not in ('android', 'ios'):
            Window.size = (900, 405)            # на ПК — окно как телефон в горизонтали
        elif FORCE_LANDSCAPE:
            try:                                # 6 = SENSOR_LANDSCAPE (обе горизонтали)
                from jnius import autoclass
                autoclass('org.kivy.android.PythonActivity').mActivity.setRequestedOrientation(6)
            except Exception:
                pass                            # не страшно: игра подстроится под любую ориентацию
        try:
            Window.softinput_mode = 'below_target'          # клавиатура не закрывает окошко кода
        except Exception:
            pass
        self.game = Game(os.path.join(self.user_data_dir, 'best.json'))
        return self.game

    def on_pause(self):
        self.game.pause()
        return True

    def on_resume(self):
        self.game.refresh_display()

    def on_stop(self):
        self.game.lan_close()


